def walk_files(root: Path, skip_dirs: set[str]):
    for l, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in skip_dirs and not d.startswith("."))
        for fn in sorted(filenames):
            path = Path(l) / fn
            if path.is_file():
                yield path
